import numpy as np

def check_equation(eps, del_val):
    """Checks if 2(eps + del_val) equals 11(eps^2 + del_val^2) - 20*eps*del_val."""
    LHS = 2 * (eps + del_val)
    RHS = 11 * (eps**2 + del_val**2) - 20 * eps * del_val
    return abs(LHS - RHS)

# Search over small deviations, constrained by |del - eps| < 0.1
eps_steps = np.linspace(0.001, 0.05, 50)
delta_steps = np.linspace(0.001, 0.05, 50)

best_match = None
min_error = float('inf')

for eps in eps_steps:
    for del_val in delta_steps:
        if abs(del_val - eps) < 0.1:
            error = check_equation(eps, del_val)
            if error < min_error:
                min_error = error
                best_match = (eps, del_val)

if best_match:
    eps_sol, delta_sol = best_match
    print(f"Found best numerical match (smallest error):")
    print(f"  Epsilon (ε): {eps_sol}")
    print(f"  Delta (δ): {delta_sol}")
    print(f"  Error (difference): {min_error}")
else:
    print("No match found in the specified small region.")

